const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;
const suppliedSecret = headers['x-xvond-n8n-secret'] || headers['X-Xvond-N8N-Secret'];
const expectedSecret = $env.N8N_SHARED_SECRET;
const requestId = String(body.request_id || headers['x-xvond-request-id'] || '');
const action = String(body.action || '').trim();
const data = body.data && typeof body.data === 'object' ? body.data : {};
const fail = (error, code, extra = {}) => [{ json: { success: false, request_id: requestId, action, data: null, error_code: code, error, ...extra } }];
if (!expectedSecret || suppliedSecret !== expectedSecret) return fail('Unauthorized channel workflow request', 'unauthorized');
if (!requestId || !body.company_id || !body.agent_id || !action) return fail('Invalid channel workflow request contract', 'invalid_contract');
if (!['channel.check', 'channel.send'].includes(action)) return fail('Unsupported channel workflow action', 'unsupported_action');
const channelId = Number(data.channel_id || 0);
const channelType = String(data.channel_type || '').trim().toLowerCase();
if (!channelId || !channelType) return fail('Channel identity is required', 'invalid_channel');
let registry = {};
try { registry = JSON.parse($env.XVOND_WORKFLOW_CHANNELS_JSON || '{}'); }
catch (_e) { return fail('Channel route registry is invalid', 'provider_not_configured'); }
const routeKey = `${body.company_id}:${channelId}`;
const target = registry[routeKey];
if (!target || target.type !== 'webhook' || typeof target.url !== 'string' || !target.url.startsWith('https://')) {
  return fail('Managed channel route is not configured', 'provider_not_configured');
}
const targetChannelType = String(target.channel_type || channelType).trim().toLowerCase();
if (targetChannelType !== channelType) return fail('Managed channel route type mismatch', 'route_mismatch');
if (action === 'channel.check') {
  return [{ json: {
    success: true,
    request_id: requestId,
    action,
    data: { connected: true, channel_id: channelId, channel_type: channelType, route_key: routeKey },
    error: null
  }}];
}
const contact = String(data.external_contact_id || '').trim();
const message = String(data.message || '').trim();
const idempotencyKey = String(data.idempotency_key || '').trim();
if (!contact || !message || !idempotencyKey) return fail('Channel send requires contact, message and idempotency key', 'invalid_send_contract');
return [{ json: {
  _dispatch: 'send',
  request_id: requestId,
  action,
  company_id: Number(body.company_id),
  agent_id: Number(body.agent_id),
  channel_id: channelId,
  channel_type: channelType,
  external_contact_id: contact,
  message,
  idempotency_key: idempotencyKey,
  route_key: routeKey,
  route_url: target.url,
  route_secret: String(target.secret || '')
}}];

const route = $('Validate Channel Route').first().json;
const provider = $input.first().json || {};
const success = provider.success === true;
const providerMessageId = provider.provider_message_id ?? provider.message_id ?? provider.id ?? null;
return [{ json: {
  success,
  request_id: route.request_id,
  action: route.action,
  data: success ? {
    connected: true,
    channel_id: route.channel_id,
    channel_type: route.channel_type,
    provider_message_id: providerMessageId == null ? null : String(providerMessageId)
  } : null,
  error_code: success ? null : String(provider.error_code || provider.code || 'provider_send_failed'),
  error: success ? null : 'Managed channel provider delivery failed'
}}];
